$_MODULE['<{amazonmarketplacepro}prestashop>configure_c37fbb2c2feddaecff0e108da07ec026'] = 'Las direcciones de retransmisión de Amazon caducan pasado un tiempo; una dirección sintética evita que los correos de la tienda reboten. La mensajería con el comprador a través de Amazon sigue funcionando.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_af6dd5c53d00465bccc957cc7b971ba0'] = 'Eliminar los datos del comprador después de';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_07e932ebe6b3a0cfb938682b7f857e92'] = 'La política de protección de datos de Amazon obliga a eliminar los datos del comprador en un plazo de 30 días desde la entrega. Cuando un pedido está finalizado y es más antiguo que ese plazo, el módulo borra de su propia tabla el nombre, el correo, la calle, la ciudad, la región, el código postal y el teléfono del comprador, además de la carga útil de Amazon almacenada. Los totales, los impuestos, las comisiones y el país de destino se conservan, así que tus informes y registros de IVA no se ven afectados.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_c9274fdfe06e9b2c44c404eea92a96f1'] = 'pedido(s) pendiente(s) de borrado;';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_b534933c730ce57ed3ab62ce5c1c3150'] = 'ya borrado(s).';
