$_MODULE['<{amazonmarketplacepro}prestashop>configure_9a89fce15c653813bba97088f4242469'] = 'Desactivar esto significa conservar los datos del comprador de Amazon más tiempo del que Amazon permite. Hazlo solo si tienes una obligación legal que lo exija y puedes acreditarla.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_114fc58e687755f400c4ff77e00b9cf7'] = 'Anonimizar también el cliente y la dirección de PrestaShop';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_06d16f3c4536d713eafb1f97f25657f4'] = 'No (recomendado)';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_b3a631ecd8088b96eeab29ebb7670789'] = 'Desactivada por defecto a propósito. PrestaShop compone las facturas a partir de la dirección guardada, así que anonimizarla altera documentos que la ley puede obligarte a conservar intactos, y una factura que debes conservar es justamente la excepción que permite la política de Amazon. Actívala solo después de asesorarte. Cuando está activa, un cliente se anonimiza únicamente si todos sus pedidos son pedidos de Amazon ya borrados; la ciudad, el código postal y el país se conservan para que el tratamiento del IVA siga siendo justificable.';
