$_MODULE['<{amazonmarketplacepro}prestashop>configure_f9f2d03af364aa656f60472f050f5ce9'] = 'Amazon presenta una compra en curso como un pedido «Pending». Con esta opción, el módulo retira esas unidades del stock de PrestaShop de inmediato para que ningún otro canal pueda venderlas, y las devuelve si el pedido nunca llega a ser pagadero. Requiere importar los pedidos Pending —el módulo lo hace automáticamente al activarla— y el cron remote_cart para liquidar las reservas.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_606e569ed905da68a3f26de02575c6d9'] = 'Liberar una reserva después de';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_4e9a4f12657cf4a16631d3bfbbd3ea93'] = 'Periodo de gracia antes de devolver las existencias de un pedido que sigue atascado en Pending. 4 horas es un valor seguro: Amazon puede tardar en pasar un pedido a Unshipped.';
$_MODULE['<{amazonmarketplacepro}prestashop>configure_a2d4829bd7afcb0622263a02a3b7a5fc'] = 'Pedidos sin existencias suficientes';
