$_MODULE['<{amazonmarketplacepro}prestashop>configure_dacbbee8d1ca69a51619dc28dcd68e21'] = 'Cuando está activada, los pedidos preparados cuyos productos no tienen existencias (y no admiten venta sin stock) esperan en la pestaña Pedidos pendientes en lugar de convertirse en pedidos de PS.';
