$_MODULE['<{amazonmarketplacepro}prestashop>configure_b1481f64dd0ca696a1845d6585cb098b'] = 'Cada llamada ejecuta solo lo que la tabla de abajo marca como pendiente, así que un cron de cinco minutos no significa una sincronización cada cinco minutos.';
