$_MODULE['<{amazonmarketplacepro}prestashop>configure_123999c78f3b0fb3c2882359df62183a'] = 'Trae los anuncios de Amazon a PrestaShop. El primer paso solo lee y compara; en el segundo eliges qué escribir, después de mirar la tabla.';
